  },
  "multa": {
    "porcentagem": 0,
    "total": 0,
    "composicao": {
      "descricao": "Se 'total_bruto' != 'total_bruto_esperado' ou 'total_inconsistencias' > 0, há multa de 35%.",
      "total_bruto_esperado": 301226.3,
      "total_inconsistencias": 218.9
    }
  },
  "pagamentos": {
